//philip.bertani@gmail.com

//code golfed by fabriceneyret2

#define R(a)  mat2(cos(a + 1.57*vec4(0,-1,1,0)))  //rotation matrix using pi/2 phase offset for sin
#define N     normalize

float t, e=1., l=0., d, i=0.; // globals
vec2 mm;  //Mouse

float param1=.1;

//thanks Shane for the meat of this f(): https://www.shadertoy.com/view/XsKXzc
float f(vec3 p) {
    vec3  o = vec3(1,-1,1), q;
    float d=100.,i=0.;

    for( p.xz *= R(t/3.), p.yz *= R(t/5.) ; i++<42. ; )

        p.xy *= R(mm.x), p.xz *= R(mm.y),
        p = ( cos(p)*p ),  //changed from abs(p)

#define S(p) p.x < p.y ? p = p.yx : p     
        S(p.xy),S(p.xz), S(p.yz),

        p -= o*.002; 
        q = p ;

        vec2 h = vec2(param1,2.);
        d = min(d, max(p.z-h.y,max(p.x*.866+p.y*.5,-p.y)-h.x*.5) ); 

    return d ;
}

void mainImage(out vec4 O, vec2 U) {
    t = iTime;
    vec3 R = iResolution, E = vec3(1,-1,-1), n,
         L =  vec3( sin(t),cos(t),0),        // light pos
         D = N( vec3( U+U,-R.y) - R.xyy ),   // ray pos and dir
         P = R-R; P.z = max(0., .3 - max(.7*sin(t/3.),0.));

    mm = vec2(2.); 

    for ( O-=O ; i++<1e2 && l<3. && e>0.; P += d*D ) {
        l += d = f(P)*.8;
        e = d - (1.+l*l)/4e4;
        if( e < 0. ) {
            P += e*D;
            L = N(L-P);
#define F(x)  x* f( P + (1.+l*l)/2e3 *x )
            n = N( F(E.x)+F(E.yyx)+F(E)+F(E.yxy) );  // normal vec
            O.rgb =  .4* max(0.,dot(-n,L)) *vec3(.8,.6,0.)
                    + pow(max(0.,dot(reflect(-D,n),L)),16.) * vec3(.9,.8,.3);
            O = pow( 6.*(1.-exp(-O*O))/exp(l*l*60.),vec4(.5) ); 
            break; 
          }
    }
}
